{"files":{"benchmarks_dev2/agent10/task_e11_min_coins/solution.py":""""Solution for task_e11_min_coins.

The implementation uses a dynamic programming approach to find the minimal number of coins
for a given amount.  When several multisets use the same minimal number of coins, the
lexicographically largest descending list is chosen.  The code performs strict type
checking and raises the appropriate exceptions as required by the task specification.
"""

from __future__ import annotations

from typing import Iterable, List, Optional, Tuple


# Helper function to validate inputs

def _validate_inputs(coins: Iterable[int], amount: int) -> None:
    """Validate the inputs according to the task specification.

    Raises:
        TypeError: if the types are incorrect.
        ValueError: if coin values are <= 0 or amount is negative.
    """
    if not isinstance(coins, (list, tuple)):
        raise TypeError("coins must be a list or tuple")
    if not isinstance(amount, int) or isinstance(amount, bool):
        raise TypeError("amount must be an int")
    if amount < 0:
        raise ValueError("amount must be non‑negative")
    for c in coins:
        if not isinstance(c, int) or isinstance(c, bool):
            raise TypeError("coins must contain only int values")
        if c <= 0:
            raise ValueError("coin values must be positive")


# Core algorithm

def min_coins(coins: Iterable[int], amount: int) -> Optional[List[int]]:
    """Return the fewest‑coin solution for ``amount`` using ``coins``.

    The result is a list of coin values sorted in descending order.  If multiple
    multisets use the same minimal number of coins, the lexicographically largest
    descending list is returned.  ``None`` is returned when the amount cannot be
    formed.
    """
    _validate_inputs(coins, amount)

    if amount == 0:
        return []

    # Convert coins to a sorted unique list for deterministic behaviour
    unique_coins = sorted(set(coins), reverse=True)
    if not unique_coins:
        return None

    # DP array: best[amt] = (num_coins, tuple_descending)
    best: List[Optional[Tuple[int, Tuple[int, ...]]]] = [None] * (amount + 1)
    best[0] = (0, ())  # zero amount requires zero coins

    for a in range(1, amount + 1):
        candidate = None
        for c in unique_coins:
            if c > a:
                continue
            prev = best[a - c]
            if prev is None:
                continue
            num, seq = prev
            new_seq = (c,) + seq
            new_candidate = (num + 1, new_seq)
            if candidate is None:
                candidate = new_candidate
            else:
                # Prefer fewer coins
                if new_candidate[0] < candidate[0]:
                    candidate = new_candidate
                elif new_candidate[0] == candidate[0]:
                    # Tie: choose lexicographically larger descending list
                    if new_candidate[1] > candidate[1]:
                        candidate = new_candidate
        best[a] = candidate

    result = best[amount]
    if result is None:
        return None
    # Convert tuple back to list
    return list(result[1])


