# Helper to percent-decode with UTF-8, preserving invalid sequences literally
# and replacing invalid UTF-8 with U+FFFD

def _percent_decode(s: str) -> str:
    """Decode percent-encoded sequences in *s*.
    Invalid percent-encodings are left as-is. Invalid UTF-8 bytes are replaced
    with the replacement character U+FFFD.
    """
    # Find all %XX patterns
    res = []
    i = 0
    while i < len(s):
        if s[i] == '%':
            if i + 2 < len(s) and re.fullmatch(r'[0-9A-Fa-f]{2}', s[i+1:i+3]):
                byte = int(s[i+1:i+3], 16)
                res.append(byte)
                i += 3
            else:
                # Invalid percent sequence, keep literally
                res.append(s[i])
                i += 1
        else:
            res.append(s[i].encode('latin1'))
            i += 1
    # Now res is a list of bytes or single chars; convert to bytes
    byte_seq = b''.join(b if isinstance(b, bytes) else b.encode('latin1') for b in res)
    try:
        return byte_seq.decode('utf-8', errors='replace')
    except Exception:
        # Should not happen, but fallback
        return byte_seq.decode('utf-8', errors='replace')


def _decode_component(comp: str) -> str:
    """Replace '+' with space, then percent-decode."""
    comp = comp.replace('+', ' ')
    return _percent_decode(comp)


def parse_query(qs: str):
    if not isinstance(qs, str):
        raise TypeError('qs must be a string')
    # Remove leading '?' only if present
    if qs.startswith('?'):
        qs = qs[1:]
    result = {}
    key_order = []
    pairs = qs.split('&') if qs else []
    for pair in pairs:
        if pair == '':
            continue
        if '=' in pair:
            key_enc, val_enc = pair.split('=', 1)
        else:
            key_enc, val_enc = pair, ''
        key = _decode_component(key_enc)
        if key == '':
            continue
        val = _decode_component(val_enc)
        # Handle array notation
        is_array = key.endswith('[]')
        if is_array:
            key = key[:-2]
        # Insert into result
        if key in result:
            # Already present
            if isinstance(result[key], list):
                result[key].append(val)
            else:
                result[key] = [result[key], val]
        else:
            # First occurrence
            key_order.append(key)
            if is_array:
                result[key] = [val]
            else:
                result[key] = val
    # Ensure order of keys as per first appearance
    ordered = {k: result[k] for k in key_order}
    return ordered
